<?php

namespace App\Medical\Documents;

use App\Medical\Ai\Work\WorkDir;
use App\Wishlist\Catalog\ImageProcessor;
use Symfony\Component\Process\Exception\ProcessTimedOutException;
use Symfony\Component\Process\Process;
use Throwable;

/**
 * The only code that runs the HEIC decoder (heif-dec, ai-worker image only). Turns a stored HEIC into a metadata-free JPEG
 * for one AI run. The spawn is an argv array behind a virtual memory limit with a hard timeout, only paths generated by the
 * app are passed, the decoder output goes to its own temp dir (removed in finally) and nothing it prints is kept. The
 * decode result is re-encoded through the hardened ImageProcessor, which drops EXIF, GPS and XMP.
 */
final class HeicConverter
{
    /** Writes the JPEG to $absJpegOut. False on any failure; never carries a path or a message out. */
    public function toJpeg(string $absHeic, string $absJpegOut): bool
    {
        $dir = null;
        try {
            $dir = WorkDir::makeTempDir();
            $kb = (int) config('ai.heic.ulimit_kb');
            $p = new Process(
                ['sh', '-c', 'ulimit -v '.$kb.'; exec "$@"', 'sh', (string) config('ai.heic.binary'), $absHeic, $dir.'/d.jpg'],
                $dir,
            );
            $p->setTimeout((float) config('ai.heic.timeout'));
            try {
                $p->run();
            } catch (ProcessTimedOutException) {
                $p->stop(0, SIGKILL);

                return false;
            }
            if ($p->getExitCode() !== 0) {
                return false;
            }

            // A container with several images may write d-1.jpg, d-2.jpg ...: the primary image is d.jpg, else the lowest number.
            $src = $dir.'/d.jpg';
            if (! is_file($src)) {
                $numbered = glob($dir.'/d-*.jpg') ?: [];
                natsort($numbered);
                $src = (string) (array_values($numbered)[0] ?? '');
            }
            if ($src === '' || ! is_file($src)) {
                return false;
            }
            $bytes = file_get_contents($src);
            if ($bytes === false || $bytes === '') {
                return false;
            }
            @unlink($src);

            $image = app(ImageProcessor::class)->process(
                $bytes,
                (int) config('ai.heic.max_jpeg_bytes'),
                (int) config('medical.image_full_px'),
                (int) config('medical.image_thumb_px'),
                (int) config('medical.image_jpeg_quality'),
                (int) config('medical.image_decode_budget_bytes'),
            );
            unset($bytes);

            return file_put_contents($absJpegOut, $image->fullBytes) !== false;
        } catch (Throwable) {
            return false;
        } finally {
            if ($dir !== null) {
                WorkDir::removeTree($dir);
            }
        }
    }
}
